<?php
require_once __DIR__.'/assert.php';
$app=require __DIR__.'/ci3_bootstrap.php';$db=$app->db;require_once APPPATH.'libraries/Clinical_amendment_service.php';
$base=70000+(int)(microtime(true)*100)%10000;$u=$base+1;$fac='T9A-'.$base;
$db->query('INSERT INTO m_puskesmas (kode_pkm,nama_puskesmas,status) VALUES (?,?,?)',[$fac,'T9A','aktif']);
$db->query('INSERT INTO users (userId,nama,email,username,password,role,status,must_change_password,remark) VALUES (?,?,?,?,?,?,?,?,?)',[$u,'T9A'.$u,'t9a'.$u.'@invalid','t9a'.$u,'x','dokter','aktif',0,$fac]);
$db->query('INSERT INTO puskesmas_staff (staff_id,kode_pkm,user_id,nama,profesi,status) VALUES (?,?,?,?,?,?)',[$u,$fac,$u,'T9A','dokter','aktif']);
$db->query('INSERT INTO requests (request_id,user_id,location,request_status,assigned_puskesmas_code,assigned_puskesmas_name,visit_status,consultation_mode,responsible_doctor_user_id) VALUES (?,?,?,?,?,?,?,?,?)',[$base,$u,'x','Accepted',$fac,'T9A','completed','non_visit',$u]);
$db->query('INSERT INTO medicalrecords (request_id,diagnosis,treatment,recommendations,anamnesis,responsible_doctor_user_id,recorded_by_user_id,clinical_finalized_at,clinical_finalized_by_user_id) VALUES (?,?,?,?,?,?,?,NOW(6),?)',[$base,'initial','initial','initial','history',$u,$u,$u]);$record=(int)$db->insert_id();
$tmp=sys_get_temp_dir().'/t9a-'.$base.'-'.getmypid();mkdir($tmp,0777,true);$gate=$tmp.'/start';$annA=$tmp.'/a';$annB=$tmp.'/b';
$spawn=function($request,$recordId,$user,$reason,$key,$value,$ann)use($tmp,$gate){$cmd=escapeshellarg(PHP_BINARY).' '.escapeshellarg(__DIR__.'/amendment_worker.php').' '.implode(' ',array_map('escapeshellarg',[$request,$recordId,$user,$reason,'diagnosis',$value,$key,$ann,$gate]));$pipes=[];$p=proc_open($cmd,[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes);$d=microtime(true)+10;while(!is_file($ann)&&microtime(true)<$d)usleep(20000);return[$p,$pipes];};
$collect=function($z){[$p,$pipes]=$z;$d=microtime(true)+15;$o='';while(microtime(true)<$d){$s=proc_get_status($p);$o.=stream_get_contents($pipes[1]);if(!$s['running'])break;usleep(20000);}foreach($pipes as $h){if(is_resource($h))fclose($h);}if(proc_get_status($p)['running'])proc_terminate($p);proc_close($p);return json_decode(trim($o),true)?:[];};
try{$replayKey='t9a-replay-'.$base;$a=$spawn($base,$record,$u,'Exact replay amendment',$replayKey,'amended',$annA);$b=$spawn($base,$record,$u,'Exact replay amendment',$replayKey,'amended',$annB);file_put_contents($gate,'x');$ra=$collect($a);$rb=$collect($b);$n=(int)$db->where('record_id',$record)->count_all_results('clinical_amendments');$e=(int)$db->where('request_id',$base)->where('event_type','clinical_record.amended')->count_all_results('request_events');vcw_assert_same(1,$n,'one exact replay amendment header');vcw_assert_same(1,$e,'one exact replay amendment event');vcw_assert_true(($ra['ok']??false)&&($rb['ok']??false),'exact replay succeeds for both workers');vcw_assert_same((int)($ra['result']['amendment_id']??0),(int)($rb['result']['amendment_id']??0),'exact replay returns canonical amendment');vcw_assert_same(1,(int)!empty($ra['result']['idempotent'])+(int)!empty($rb['result']['idempotent']),'exact replay has one idempotent response');$confRequest=$base+100;$confUser=$confRequest+1;$confFacility='T9A-'.$confRequest;$db->query('INSERT INTO m_puskesmas (kode_pkm,nama_puskesmas,status) VALUES (?,?,?)',[$confFacility,'T9A Conflict','aktif']);$db->query('INSERT INTO users (userId,nama,email,username,password,role,status,must_change_password,remark) VALUES (?,?,?,?,?,?,?,?,?)',[$confUser,'T9A'.$confUser,'t9a'.$confUser.'@invalid','t9a'.$confUser,'x','dokter','aktif',0,$confFacility]);$db->query('INSERT INTO puskesmas_staff (staff_id,kode_pkm,user_id,nama,profesi,status) VALUES (?,?,?,?,?,?)',[$confUser,$confFacility,$confUser,'T9A','dokter','aktif']);$db->query('INSERT INTO requests (request_id,user_id,location,request_status,assigned_puskesmas_code,assigned_puskesmas_name,visit_status,consultation_mode,responsible_doctor_user_id) VALUES (?,?,?,?,?,?,?,?,?)',[$confRequest,$confUser,'x','Accepted',$confFacility,'T9A Conflict','completed','non_visit',$confUser]);$db->query('INSERT INTO medicalrecords (request_id,diagnosis,treatment,recommendations,anamnesis,responsible_doctor_user_id,recorded_by_user_id,clinical_finalized_at,clinical_finalized_by_user_id) VALUES (?,?,?,?,?,?,?,NOW(6),?)',[$confRequest,'initial','initial','initial','history',$confUser,$confUser,$confUser]);$confRecord=(int)$db->insert_id();$confAnnA=$tmp.'/conflict-a';$confAnnB=$tmp.'/conflict-b';$confKey='t9a-conflict-'.$confRequest;$c=$spawn($confRequest,$confRecord,$confUser,'Competing reason A',$confKey,'amended-a',$confAnnA);$d=$spawn($confRequest,$confRecord,$confUser,'Competing reason B',$confKey,'amended-b',$confAnnB);$rc=$collect($c);$rd=$collect($d);vcw_assert_same(1,(int)!empty($rc['ok'])+(int)!empty($rd['ok']),'conflicting key race has one winner');vcw_assert_same(1,(int)(($rc['code']??null)==='AMENDMENT_KEY_CONFLICT')+(int)(($rd['code']??null)==='AMENDMENT_KEY_CONFLICT'),'conflicting key race rejects one context');vcw_assert_same(1,(int)$db->where('record_id',$confRecord)->count_all_results('clinical_amendments'),'conflicting key race one amendment header');vcw_assert_same(1,(int)$db->where('request_id',$confRequest)->where('event_type','clinical_record.amended')->count_all_results('request_events'),'conflicting key race one amendment event');echo "TASK9_AMENDMENT_HARNESS=PASS\nTASK9_AMENDMENT_INDEPENDENT_WORKERS=PASS\nTASK9_AMENDMENT_HARNESS_CLEANUP=PASS\nTASK9_AMENDMENT_EXACT_REPLAY=PASS\nTASK9_AMENDMENT_KEY_CONFLICT_RACE=PASS\n";}finally{if(is_file($gate))@unlink($gate);foreach([$annA,$annB,$confAnnA??'', $confAnnB??''] as $f){if($f!==''&&is_file($f))@unlink($f);}@rmdir($tmp);}
